/* ---------- COLOUR face (Tilt Brush style wheel): hue and saturation on the wheel, brightness and opacity on bars, skin tones to tap; it sets the page's own colour inputs ---------- */
const CW={cx:256,cy:262,R:122,vx:40,vw:432,vy:420,oy:474,sy:526};
let wheelImg=null;
function hex2hsv(hex){ const m=/^#?([0-9a-f]{6})$/i.exec(String(hex||'')); const n=m?parseInt(m[1],16):0xd9a583; const r=(n>>16&255)/255,g=(n>>8&255)/255,b=(n&255)/255; const mx=Math.max(r,g,b), mn=Math.min(r,g,b), d=mx-mn; let h=0; if(d){ if(mx===r) h=((g-b)/d)%6; else if(mx===g) h=(b-r)/d+2; else h=(r-g)/d+4; h/=6; if(h<0) h+=1; } return {h,s:mx?d/mx:0,v:mx}; }
