  const toggle={ label:()=>'Light balls: '+((LO.dotsOn&&LO.dotsOn())?'shown (tap to hide)':'hidden (tap to show)'), act:()=>{ const on=!(LO.dotsOn&&LO.dotsOn()); S.lightDots=on; try{ LO.dots&&LO.dots(on); }catch(e){} say(on?'Light balls shown: grab one to move that light':'Light balls hidden: the lights still shine'); } };
