  const bar=(y,label,f,grad,drag)=>{ c.textAlign='left'; c.font='16px system-ui,sans-serif'; c.fillStyle='#b0a6bb'; c.fillText(label,CW.vx,y-6); const g=c.createLinearGradient(CW.vx,0,CW.vx+CW.vw,0); grad.forEach((cc,i)=>g.addColorStop(i/(grad.length-1),cc)); c.fillStyle=g; c.fillRect(CW.vx,y,CW.vw,30); c.strokeStyle='rgba(255,255,255,.35)'; c.lineWidth=2; c.strokeRect(CW.vx,y,CW.vw,30); const kx=CW.vx+CW.vw*f; c.fillStyle='#fff'; c.fillRect(kx-4,y-5,8,40); c.strokeStyle='#000'; c.lineWidth=1; c.strokeRect(kx-4,y-5,8,40); rects.push({x:CW.vx-8,y:y-8,w:CW.vw+16,h:46,b:{label:'col:'+label,drag}}); c.textAlign='center'; };
