const FK_DIG=[['1'],['2'],['3'],['4'],['5'],['6'],['7'],['8'],['9'],['0'],['⌫',1.6]], FK_BOT=(a)=>[[a,1.6],['space',5],['-'],["'"],['Clear',1.6],['Done',2.2]];
const FK_LAYERS=[   /* 0 letters, 1 symbols, 2 more symbols and accents (Ruth 2026-10-11: the normal keyboard with all the extra symbols) */
  [FK_DIG, [['q'],['w'],['e'],['r'],['t'],['y'],['u'],['i'],['o'],['p']], [['a'],['s'],['d'],['f'],['g'],['h'],['j'],['k'],['l']], [['⇧',1.5],['z'],['x'],['c'],['v'],['b'],['n'],['m'],[','],['.']], FK_BOT('?123')],
  [FK_DIG, [['!'],['@'],['#'],['$'],['%'],['^'],['&'],['*'],['('],[')']], [['-'],['_'],['='],['+'],['['],[']'],['{'],['}'],[';'],[':']], [['=\\<',1.5],["'"],['"'],[','],['.'],['?'],['/'],['\\'],['|'],['~']], FK_BOT('abc')],
  [FK_DIG, [['€'],['£'],['¥'],['°'],['•'],['©'],['®'],['™'],['±'],['×']], [['÷'],['¿'],['¡'],['§'],['¶'],['…'],['–'],['—'],['«'],['»']], [['123',1.5],['ä'],['ö'],['ü'],['é'],['è'],['ñ'],['ç'],['å'],['ß']], FK_BOT('abc')] ];
function fkbWant(o){ FKB.want=o; }
function fkbPref(){ if(FKB._pref) return FKB._pref; let p=null; try{ p=JSON.parse(localStorage.getItem('vrKbdV1')||'null'); }catch(e){} if(!p||!Array.isArray(p.off)||!(p.sc>0)) p={sc:.6,off:[0,-.32,.46]}; FKB._pref=p; return p; }   /* where you left the keyboard, kept for good (Ruth 2026-10-11) */
function fkbAxes(){ const inv=new M4().copy(dolly.matrixWorld).invert(); const fw=new V3(0,0,-1).transformDirection(O.camera.matrixWorld).transformDirection(inv); fw.y=0; if(fw.lengthSq()<1e-4) fw.set(0,0,-1); fw.normalize(); return {fw,right:new V3(-fw.z,0,fw.x)}; }
