  { const gh=FKB.hv==='grab'||!!FKB.mv; rr(c,Wd/2-150,7,300,30,15); c.fillStyle=gh?'rgba(255,211,90,.22)':'rgba(255,255,255,.07)'; c.fill(); c.fillStyle=gh?'#ffd35a':'rgba(255,255,255,.42)'; for(let r_=0;r_<2;r_++) for(let k_=0;k_<14;k_++){ c.beginPath(); c.arc(Wd/2-91+k_*14,15+r_*14,3.3,0,6.2832); c.fill(); } FKB.rects.push({x:0,y:0,w:Wd,h:FKB.GY,label:'grab'}); }   /* the dotted grip: hold it, then stick forward/back = farther/closer, left/right = smaller/bigger */
