function gloveFrame(){ ctrls.forEach(st=>{ if(!st.glove) return; const gp=st.src&&st.src.gamepad; const tr=gp&&gp.buttons[0]?gp.buttons[0].value:0, sq=gp&&gp.buttons[1]?gp.buttons[1].value:0; st.glove.visible=!st.isHand;
    st.fing.forEach((segs,i)=>{ const k=i===0?Math.max(tr*1.0,sq*0.55):sq; const base=0.35+k*0.95; segs.forEach((j,n)=>{ j.rotation.y=base*(n===0?0.8:1.0); }); }); st.thumb.rotation.x=0.5-Math.max(tr,sq)*0.35; }); }

