  S.gravRings.visible=!!S.ringsOn; while(S.gravMeshes.length<rings.length){ const m=new T.Mesh(new T.RingGeometry(0.8,1,28),new T.MeshBasicMaterial({color:0x4fe0c8,transparent:true,opacity:.75,side:T.DoubleSide,depthTest:false})); m.rotation.x=-Math.PI/2; m.renderOrder=990; S.gravRings.add(m); S.gravMeshes.push(m); }
