  const sec={name:title,root:null,back:goBack,rows:()=>[...el.options].map((o,i)=>({type:'btn',label:clean(o.text||o.value).slice(0,40)||('Option '+(i+1)),on:i===el.selectedIndex,act(){ el.selectedIndex=i; el.dispatchEvent(new Event('input',{bubbles:true})); el.dispatchEvent(new Event('change',{bubbles:true})); say('Chose '+clean(o.text).slice(0,30)); goBack(); }}))};
