  const cx=(O.noteContext&&O.noteContext())||{}; let after=null, changes=[]; try{ after=cx.snap&&cx.snap(); if(S.pauseSnap&&after) changes=poseDiff(S.pauseSnap,after).map(c=>({slot:(cx.slots||[])[c.i],joint:c.joint,deg:c.deg})); }catch(e){}
  const p=await jointShot(); if(!p){ say('Joint capture failed: no picture'); return; } pulse(50);
  NOTE.pending.push({blob:null,photos:[p],secs:0,changes,after,before:S.pauseSnap||null,headset:headsetSnap(),ctx:{scene:cx.scene,project:cx.project,title:cx.title,cast:cx.cast,songT:cx.songT,locked:[...S.locks.keys()].map(i=>jointName(i)),capture:true}}); NOTE.sent=null;
